#[derive(Clone, Copy, PartialEq, Eq)]
enum SarSubView {
    PivotHeatmap,
    SubstituentWeightsAndRows,
    VirtualAnalogs,
}

type AsyncIngestResult = Result<(Vec<Molecule>, IngestReport, bool), String>;

pub fn run_gui(ds: DatasetAnalysis, vsync: bool) -> eframe::Result<()> {
    let mut wgpu_options = egui_wgpu::WgpuConfiguration::default();
    wgpu_options.present_mode = if vsync {
        wgpu::PresentMode::AutoVsync
    } else {
        wgpu::PresentMode::AutoNoVsync
    };

    let native_options = eframe::NativeOptions {
        viewport: egui::ViewportBuilder::default()
            .with_inner_size([1620.0, 960.0])
            .with_min_inner_size([1140.0, 700.0])
            .with_title(
                "SAR-Atlas v3.8.0 — 5-Domain Small-Molecule, FBDD, Macrocycle, PROTAC, SMARTCyp, Prodrug & Oral PBPK Workbench",
            ),
        renderer: eframe::Renderer::Wgpu,
        wgpu_options,
        ..Default::default()
    };

    eframe::run_native(
        "sar-atlas",
        native_options,
        Box::new(|cc| Ok(Box::new(SarAtlasGuiApp::new(cc, ds)))),
    )
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum CampaignSeriesPreset {
    Egfr1m17,
    Drd26cm4,
    Cox23ln1,
    AllLoaded,
    CustomTarget,
}

#[derive(Clone, Debug)]
struct ActiveCampaignWorkspace {
    preset: CampaignSeriesPreset,
    #[allow(dead_code)]
    target_name: String,
    pdb_id: String,
    title: String,
    series_count: usize,
}

impl Default for ActiveCampaignWorkspace {
    fn default() -> Self {
        Self {
            preset: CampaignSeriesPreset::Egfr1m17,
            target_name: "EGFR".to_string(),
            pdb_id: "1M17".to_string(),
            title: "EGFR Kinase Campaign".to_string(),
            series_count: 8,
        }
    }
}

impl ActiveCampaignWorkspace {
    fn badge_text(&self) -> String {
        format!("{} • PDB {} • n={}", self.title, self.pdb_id, self.series_count)
    }
}

